.onreadystatechange = function() {

    if (this.readyState === 4 && this.status === 200) {

        const data = JSON.parse(this.responseText);

        if (data.hotels.length > 0) {

            console.log("Found hotels:", data.hotels);

            document.getElementById("hotels").innerHTML = data.hotels.map(hotel => `

                <div class="hotel-card">

                    <h3>${hotel.name}</h3>

                    <p>Price: €${hotel.price} per night</p>

                    <p>Rating: ⭐⭐⭐⭐⭐ ${hotel.rating}</p>

                    <p>Distance to center: ${hotel.distance}</p>

                </div>

            `).join("");

        } else {

            document.getElementById("hotels").innerHTML = "<p>No matching hotels found.</p>";

        }

    }

};

